/**
 * Tapla — yonlendirme + panel + PWA
 *
 * YOLLAR
 *   /r/<kod>                 kart yonlendirmesi (+ okutma sayaci)
 *   /p/<token>               isletme paneli (PWA)
 *   /p/manifest.json         PWA manifesti
 *   /p/sw.js                 service worker
 *   /p/ikon-192.png          ikon
 *   /p/ikon-512.png          ikon
 *   /api/p/<token>           panel verisi (JSON)
 *
 * YONETIM (ADMIN_KEY ister)
 *   /ekle?key=&kod=&hedef=&isletme=        kart tanimla
 *   /stat/<kod>?key=                        kart istatistigi
 *   /isletme?key=&token=&ad=&kodlar=a,b,c   panel hesabi olustur/guncelle
 *   /ozet?key=&token=        (POST, JSON)   rapor ozetini yaz
 *
 * KV ANAHTARLARI
 *   kart:<kod>        {hedef, isletme, not}
 *   tap:<kod>         toplam okutma
 *   gun:<kod>:<gun>   gunluk okutma
 *   isletme:<token>   {ad, kodlar:[]}
 *   ozet:<token>      {puan, onceki_puan, toplam_yorum, yeni_yorum, guncelleme, temalar[], son_yorumlar[]}
 */

const SURUM = "v7";
const IKON192 = "";
const IKON512 = "";

const b64bin = (s) => {
  const ham = atob(s);
  const buf = new Uint8Array(ham.length);
  for (let i = 0; i < ham.length; i++) buf[i] = ham.charCodeAt(i);
  return buf;
};

const json = (o, durum = 200) =>
  new Response(JSON.stringify(o), {
    status: durum,
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" },
  });

const bugun = () => new Date().toISOString().slice(0, 10);
const gunOnce = (n) => new Date(Date.now() - n * 864e5).toISOString().slice(0, 10);

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    let p = url.pathname.split("/").filter(Boolean);
    const YONETIM = ["ekle", "stat", "isletme", "ozet", "sifirla"];
    if (p[0] === "api" && YONETIM.includes(p[1])) p = p.slice(1);
    const anahtar = url.searchParams.get("key");
    const yetkili = anahtar && anahtar === env.ADMIN_KEY;

    if (p[0] === "r" && p[1]) {
      const kod = p[1];
      const ham = await env.KARTLAR.get(`kart:${kod}`);
      if (!ham) return new Response("Bu kart henuz tanimli degil.", { status: 404 });
      const kart = JSON.parse(ham);

      const amac = (request.headers.get("Sec-Purpose") ||
                    request.headers.get("Purpose") || "").toLowerCase();
      const onYukleme = amac.includes("prefetch") || amac.includes("prerender");

      const ip = request.headers.get("CF-Connecting-IP") || "?";
      const ua = request.headers.get("User-Agent") || "";
      const tekrar = `dedup:${kod}:${ip}:${ua.slice(0, 40)}`;
      const g = bugun();

      const say = async () => {
        if (await env.KARTLAR.get(tekrar)) return;
        await env.KARTLAR.put(tekrar, "1", { expirationTtl: 60 });

        if (kart.token) {
          const pham = await env.KARTLAR.get(`panel:${kart.token}`);
          const pan = pham ? JSON.parse(pham) : { toplam: 0, gunluk: {}, kartlar: {} };
          pan.toplam = (pan.toplam || 0) + 1;
          pan.gunluk[g] = (pan.gunluk[g] || 0) + 1;
          pan.kartlar[kod] = (pan.kartlar[kod] || 0) + 1;
          pan.son = new Date().toISOString();
          pan.son_kart = kod;
          const sinir = gunOnce(59);
          for (const gun of Object.keys(pan.gunluk)) if (gun < sinir) delete pan.gunluk[gun];
          await env.KARTLAR.put(`panel:${kart.token}`, JSON.stringify(pan));
        } else {
          const t = parseInt((await env.KARTLAR.get(`tap:${kod}`)) || "0") + 1;
          await env.KARTLAR.put(`tap:${kod}`, String(t));
        }
      };
      if (request.method === "GET" && !onYukleme) ctx.waitUntil(say());

      return new Response(null, {
        status: 302,
        headers: { Location: kart.hedef, "Cache-Control": "no-store, no-cache, must-revalidate" },
      });
    }

    if (p[0] === "p" && p[1] === "manifest.json") {
      return json({
        name: "Tapla Panel",
        short_name: "Tapla",
        start_url: url.searchParams.get("t") ? `/p/${url.searchParams.get("t")}` : "/p/",
        scope: "/p/",
        display: "standalone",
        background_color: "#10243E",
        theme_color: "#10243E",
        orientation: "portrait",
        icons: [
          { src: "/p/ikon-192.png", sizes: "192x192", type: "image/png", purpose: "any maskable" },
          { src: "/p/ikon-512.png", sizes: "512x512", type: "image/png", purpose: "any maskable" },
        ],
      });
    }
    if (p[0] === "p" && (p[1] === "ikon-192.png" || p[1] === "ikon-512.png")) {
      const veri = b64bin(p[1] === "ikon-192.png" ? IKON192 : IKON512);
      return new Response(veri, {
        headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=604800" },
      });
    }
    if (p[0] === "p" && p[1] === "sw.js") {
      return new Response(SERVICE_WORKER.replaceAll("__SURUM__", SURUM), {
        headers: { "Content-Type": "application/javascript; charset=utf-8", "Cache-Control": "no-store" },
      });
    }

    if (p[0] === "api" && p[1] === "p" && p[2]) {
      const token = p[2];
      const isl = await env.KARTLAR.get(`isletme:${token}`);
      if (!isl) return json({ hata: "bulunamadi" }, 404);
      const bilgi = JSON.parse(isl);

      const pham = await env.KARTLAR.get(`panel:${token}`);
      const pan = pham ? JSON.parse(pham) : { toplam: 0, gunluk: {}, kartlar: {} };

      const g = bugun(), h7 = gunOnce(6), g30 = gunOnce(29);
      let hafta = 0, ay = 0;
      for (const [gun, adet] of Object.entries(pan.gunluk || {})) {
        if (gun >= h7) hafta += adet;
        if (gun >= g30) ay += adet;
      }

      const ozetHam = await env.KARTLAR.get(`ozet:${token}`);
      return json({
        ad: bilgi.ad,
        kart_sayisi: (bilgi.kodlar || []).length,
        isimler: bilgi.isimler || {},
        tap: { bugun: (pan.gunluk || {})[g] || 0, hafta, ay,
               toplam: pan.toplam || 0, gunluk: pan.gunluk || {}, kartlar: pan.kartlar || {},
               son: pan.son || null, son_kart: pan.son_kart || null },
        ozet: ozetHam ? JSON.parse(ozetHam) : null,
      });
    }

    if (p[0] === "p") {
      const token = p[1] || "";
      if (!token) return new Response(GIRIS_HTML, {
        headers: { "Content-Type": "text/html; charset=utf-8" } });
      const isl = await env.KARTLAR.get(`isletme:${token}`);
      if (!isl) return new Response(GIRIS_HTML.replace("<!--UYARI-->",
        '<p class="uyari">Bu bağlantı geçersiz. Lütfen size iletilen adresi kontrol edin.</p>'),
        { status: 404, headers: { "Content-Type": "text/html; charset=utf-8" } });
      return new Response(PANEL_HTML.replaceAll("__TOKEN__", token).replaceAll("__SURUM__", SURUM), {
        headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
      });
    }

    if (p[0] === "ekle") {
      if (!yetkili) return new Response("yetkisiz", { status: 401 });
      const kod = url.searchParams.get("kod"), hedef = url.searchParams.get("hedef");
      if (!kod || !hedef) return new Response("kod ve hedef gerekli", { status: 400 });
      await env.KARTLAR.put(`kart:${kod}`, JSON.stringify({
        hedef, isletme: url.searchParams.get("isletme") || "", not: url.searchParams.get("not") || "" }));
      return new Response(`OK: /r/${kod} -> ${hedef}`);
    }

    if (p[0] === "stat" && p[1]) {
      if (!yetkili) return new Response("yetkisiz", { status: 401 });
      const kod = p[1];
      const ham = await env.KARTLAR.get(`kart:${kod}`);
      if (!ham) return new Response("kart yok", { status: 404 });
      const kart = JSON.parse(ham);

      if (kart.token) {
        const pham = await env.KARTLAR.get(`panel:${kart.token}`);
        const pan = pham ? JSON.parse(pham) : { kartlar: {}, gunluk: {} };
        return json({ kod, ...kart, toplam_tap: pan.kartlar[kod] || 0,
                      isletme_toplami: pan.toplam || 0, gunluk: pan.gunluk || {} });
      }
      const toplam = (await env.KARTLAR.get(`tap:${kod}`)) || "0";
      const liste = await env.KARTLAR.list({ prefix: `gun:${kod}:` });
      const gunler = {};
      for (const k of liste.keys) gunler[k.name.split(":").pop()] = parseInt(await env.KARTLAR.get(k.name));
      return json({ kod, ...kart, toplam_tap: +toplam, gunluk: gunler });
    }

    if (p[0] === "isletme") {
      if (!yetkili) return new Response("yetkisiz", { status: 401 });
      const token = url.searchParams.get("token");
      const ad = url.searchParams.get("ad");
      const kodlar = (url.searchParams.get("kodlar") || "").split(",").map(s => s.trim()).filter(Boolean);
      if (!token || !ad) return new Response("token ve ad gerekli", { status: 400 });

      const oncekiHam = await env.KARTLAR.get(`isletme:${token}`);
      const onceki = oncekiHam ? JSON.parse(oncekiHam) : {};
      const isimler = onceki.isimler || {};
      const isimGiris = url.searchParams.get("isimler");
      if (isimGiris) {
        for (const parca of isimGiris.split("|")) {
          const [k, ...v] = parca.split("=");
          if (k && v.length) isimler[k.trim()] = v.join("=").trim();
        }
      }
      await env.KARTLAR.put(`isletme:${token}`, JSON.stringify({ ad, kodlar, isimler }));

      const pham = await env.KARTLAR.get(`panel:${token}`);
      const pan = pham ? JSON.parse(pham) : { toplam: 0, gunluk: {}, kartlar: {} };
      let tasinan = 0;

      for (const kod of kodlar) {
        const kham = await env.KARTLAR.get(`kart:${kod}`);
        if (kham) {
          const k = JSON.parse(kham);
          if (k.token !== token) {
            k.token = token;
            await env.KARTLAR.put(`kart:${kod}`, JSON.stringify(k));
          }
        }
        if (pan.kartlar[kod] === undefined) {
          const eski = parseInt((await env.KARTLAR.get(`tap:${kod}`)) || "0");
          if (eski > 0) {
            pan.kartlar[kod] = eski;
            pan.toplam += eski;
            tasinan += eski;
            const liste = await env.KARTLAR.list({ prefix: `gun:${kod}:` });
            for (const key of liste.keys) {
              const gun = key.name.split(":").pop();
              pan.gunluk[gun] = (pan.gunluk[gun] || 0) +
                parseInt((await env.KARTLAR.get(key.name)) || "0");
            }
          } else {
            pan.kartlar[kod] = 0;
          }
        }
      }
      let dusen = 0;
      for (const kod of Object.keys(pan.kartlar)) {
        if (!kodlar.includes(kod)) {
          delete pan.kartlar[kod];
          delete isimler[kod];
          dusen++;
        }
      }
      if (dusen) {
        await env.KARTLAR.put(`isletme:${token}`, JSON.stringify({ ad, kodlar, isimler }));
      }

      const sinir = gunOnce(59);
      for (const gun of Object.keys(pan.gunluk)) if (gun < sinir) delete pan.gunluk[gun];
      await env.KARTLAR.put(`panel:${token}`, JSON.stringify(pan));

      return new Response(`OK: /p/${token} -> ${ad} (${kodlar.length} kart` +
        (tasinan ? `, ${tasinan} eski okutma tasindi` : "") +
        (dusen ? `, ${dusen} kart listeden dusuruldu` : "") + ")");
    }

    if (p[0] === "sifirla") {
      if (!yetkili) return new Response("yetkisiz", { status: 401 });
      const token = url.searchParams.get("token");
      if (!token) return new Response("token gerekli", { status: 400 });
      const isl = await env.KARTLAR.get(`isletme:${token}`);
      if (!isl) return new Response("isletme bulunamadi", { status: 404 });
      const bilgi = JSON.parse(isl);

      const pham = await env.KARTLAR.get(`panel:${token}`);
      const eski = pham ? JSON.parse(pham) : { toplam: 0 };
      const oncekiToplam = eski.toplam || 0;

      const yeni = { toplam: 0, gunluk: {}, kartlar: {} };
      for (const kod of bilgi.kodlar || []) yeni.kartlar[kod] = 0;
      await env.KARTLAR.put(`panel:${token}`, JSON.stringify(yeni));

      for (const kod of bilgi.kodlar || []) await env.KARTLAR.delete(`tap:${kod}`);

      return new Response(`OK: ${bilgi.ad} paneli sifirlandi (${oncekiToplam} okutma silindi)`);
    }

    if (p[0] === "ozet") {
      if (!yetkili) return new Response("yetkisiz", { status: 401 });
      if (request.method !== "POST") return new Response("POST gerekli", { status: 405 });
      const token = url.searchParams.get("token");
      if (!token) return new Response("token gerekli", { status: 400 });
      const govde = await request.text();
      await env.KARTLAR.put(`ozet:${token}`, govde);
      return new Response(`OK: ozet:${token} yazildi (${govde.length} bayt)`);
    }

    return new Response("Tapla yonlendirme servisi", { status: 200 });
  },
};

const SERVICE_WORKER = `
const AD = 'tapla-__SURUM__';

self.addEventListener('install', e => self.skipWaiting());

self.addEventListener('activate', e => e.waitUntil((async () => {
  // eski surum onbelleklerini sil
  const adlar = await caches.keys();
  await Promise.all(adlar.filter(a => a !== AD).map(a => caches.delete(a)));
  await self.clients.claim();
})()));

self.addEventListener('message', e => {
  if (e.data === 'temizle') caches.keys().then(a => a.forEach(x => caches.delete(x)));
});

// Her sey ONCE AG: guncel surum her zaman gelir.
// Ag yoksa onbellekteki son kopya gosterilir (cevrimdisi calissin diye).
self.addEventListener('fetch', e => {
  const u = new URL(e.request.url);
  if (e.request.method !== 'GET') return;
  if (!u.pathname.startsWith('/p/') && !u.pathname.startsWith('/api/')) return;

  e.respondWith((async () => {
    try {
      const yanit = await fetch(e.request, { cache: 'no-store' });
      if (yanit && yanit.status === 200) {
        const kopya = yanit.clone();
        caches.open(AD).then(c => c.put(e.request, kopya));
      }
      return yanit;
    } catch (hata) {
      const onbellek = await caches.match(e.request);
      if (onbellek) return onbellek;
      throw hata;
    }
  })());
});
`;

